    private readonly Dictionary<string, List<string>> _reverseIndex = new(StringComparer.OrdinalIgnoreCase);

    // Frozen (read-optimized) state after Build()
    private FrozenDictionary<string, string>? _frozenCategories;
    private FrozenDictionary<string, decimal>? _frozenPrices;
    private FrozenDictionary<string, string[]>? _frozenReverseIndex;

    // Parallel arrays for SIMD-accelerated price summation
    private FrozenDictionary<string, int>? _codeToIndex;
    private double[]? _priceVector;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;

        // Maintain reverse index during population
        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_reverseIndex, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);

        // Invalidate frozen state on mutation
        _frozenCategories = null;
        _frozenPrices = null;
        _frozenReverseIndex = null;
        _codeToIndex = null;
        _priceVector = null;
    }

    /// <summary>
    /// Freezes internal dictionaries for maximum read throughput.
    /// </summary>
    public void Build()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenReverseIndex = _reverseIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);

        // Build parallel arrays for vectorized price summation
        var indexMap = new Dictionary<string, int>(_prices.Count, StringComparer.OrdinalIgnoreCase);
        _priceVector = new double[_prices.Count];
        int i = 0;
        foreach (var (code, price) in _prices)
        {
            indexMap[code] = i;
            _priceVector[i] = (double)price;
            i++;
        }
        _codeToIndex = indexMap.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        if (_frozenCategories is { } frozen)
            return frozen.TryGetValue(code, out var cat) ? cat : null;

        return _categories.TryGetValue(code, out var c) ? c : null;
    }

