        if (_codeToIndex is not null && _priceVector is not null)
            return GetTotalPriceVectorized(codes);

        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    private decimal GetTotalPriceVectorized(IEnumerable<string> codes)
    {
        var indexLookup = _codeToIndex!;
        var prices = _priceVector!;

        // Collect indices of matching codes
        Span<int> indices = codes.TryGetNonEnumeratedCount(out int count) && count <= 256
            ? stackalloc int[count]
            : new int[count > 0 ? count : 64];

        int matched = 0;
        foreach (var code in codes)
        {
            if (indexLookup.TryGetValue(code, out int idx))
            {
                if (matched >= indices.Length)
                {
                    // Grow buffer
                    var newBuf = new int[indices.Length * 2];
                    indices.CopyTo(newBuf);
                    indices = newBuf;
                }
                indices[matched++] = idx;
            }
        }

        // SIMD-accelerated gather-and-sum
        double total = SumPricesVectorized(prices, indices[..matched]);
        return (decimal)total;
    }

    private static double SumPricesVectorized(double[] prices, ReadOnlySpan<int> indices)
    {
        double sum = 0;
        int i = 0;
        int vectorSize = Vector<double>.Count;

        // Process in SIMD-width chunks using gather pattern
        if (indices.Length >= vectorSize)
        {
            Vector<double> vSum = Vector<double>.Zero;
            Span<double> gathered = stackalloc double[vectorSize];

            for (; i <= indices.Length - vectorSize; i += vectorSize)
            {
                for (int j = 0; j < vectorSize; j++)
                    gathered[j] = prices[indices[i + j]];

                vSum += new Vector<double>(gathered);
            }

            sum = Vector.Sum(vSum);
        }

        // Scalar remainder
        for (; i < indices.Length; i++)
            sum += prices[indices[i]];

        return sum;
    }

    /// <summary>
    /// Returns products in a category. O(1) lookup via reverse index.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        // Fast path: frozen reverse index
        if (_frozenReverseIndex is { } frozen)
            return frozen.TryGetValue(category, out var arr) ? new List<string>(arr) : [];

        // Fallback: mutable reverse index (still O(1))
        return _reverseIndex.TryGetValue(category, out var list) ? new List<string>(list) : [];
    }
}

