using System.Collections.Frozen;
using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// High-throughput product catalog optimized for read-heavy workloads.
/// Call <see cref="Build"/> after populating to freeze internal structures.
/// </summary>
public class ProductCatalog
{
    // Mutable state used during population
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _reverseIndex = new(StringComparer.OrdinalIgnoreCase);

    // Frozen (read-optimized) state after Build()
    private FrozenDictionary<string, string>? _frozenCategories;
    private FrozenDictionary<string, decimal>? _frozenPrices;
    private FrozenDictionary<string, string[]>? _frozenReverseIndex;

    // Parallel arrays for SIMD-accelerated price summation
    private FrozenDictionary<string, int>? _codeToIndex;
    private double[]? _priceVector;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;

        // Maintain reverse index during population
        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_reverseIndex, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);

        // Invalidate frozen state on mutation
        _frozenCategories = null;
        _frozenPrices = null;
        _frozenReverseIndex = null;
        _codeToIndex = null;
        _priceVector = null;
    }

    /// <summary>
    /// Freezes internal dictionaries for maximum read throughput.
    /// </summary>
    public void Build()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenReverseIndex = _reverseIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);

        // Build parallel arrays for vectorized price summation
        var indexMap = new Dictionary<string, int>(_prices.Count, StringComparer.OrdinalIgnoreCase);
        _priceVector = new double[_prices.Count];
        int i = 0;
        foreach (var (code, price) in _prices)
        {
            indexMap[code] = i;
            _priceVector[i] = (double)price;
            i++;
        }
        _codeToIndex = indexMap.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        if (_frozenCategories is { } frozen)
            return frozen.TryGetValue(code, out var cat) ? cat : null;

        return _categories.TryGetValue(code, out var c) ? c : null;
    }

    /// <summary>
    /// Computes total price for a batch of codes.
    /// Uses SIMD-accelerated summation over doubles when the catalog is frozen.
    /// </summary>
    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        // Fast path: vectorized summation over pre-built double array
        if (_codeToIndex is not null && _priceVector is not null)
            return GetTotalPriceVectorized(codes);

        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    private decimal GetTotalPriceVectorized(IEnumerable<string> codes)
    {
        var indexLookup = _codeToIndex!;
        var prices = _priceVector!;

        // Collect indices of matching codes
        Span<int> indices = codes.TryGetNonEnumeratedCount(out int count) && count <= 256
            ? stackalloc int[count]
            : new int[count > 0 ? count : 64];

        int matched = 0;
        foreach (var code in codes)
        {
            if (indexLookup.TryGetValue(code, out int idx))
            {
                if (matched >= indices.Length)
                {
                    // Grow buffer
                    var newBuf = new int[indices.Length * 2];
                    indices.CopyTo(newBuf);
                    indices = newBuf;
                }
                indices[matched++] = idx;
            }
        }

        // SIMD-accelerated gather-and-sum
        double total = SumPricesVectorized(prices, indices[..matched]);
        return (decimal)total;
    }

    private static double SumPricesVectorized(double[] prices, ReadOnlySpan<int> indices)
    {
        double sum = 0;
        int i = 0;
        int vectorSize = Vector<double>.Count;

        // Process in SIMD-width chunks using gather pattern
        if (indices.Length >= vectorSize)
        {
            Vector<double> vSum = Vector<double>.Zero;
            Span<double> gathered = stackalloc double[vectorSize];

            for (; i <= indices.Length - vectorSize; i += vectorSize)
            {
                for (int j = 0; j < vectorSize; j++)
                    gathered[j] = prices[indices[i + j]];

                vSum += new Vector<double>(gathered);
            }

            sum = Vector.Sum(vSum);
        }

        // Scalar remainder
        for (; i < indices.Length; i++)
            sum += prices[indices[i]];

        return sum;
    }

    /// <summary>
    /// Returns products in a category. O(1) lookup via reverse index.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        // Fast path: frozen reverse index
        if (_frozenReverseIndex is { } frozen)
            return frozen.TryGetValue(category, out var arr) ? new List<string>(arr) : [];

        // Fallback: mutable reverse index (still O(1))
        return _reverseIndex.TryGetValue(category, out var list) ? new List<string>(list) : [];
    }
}

